/*
 * Output and update for function-call system:
 *    '<S526>/detectLockup'
 *    '<S554>/detectLockup'
 *    '<S582>/detectLockup'
 *    '<S610>/detectLockup'
 *    '<S638>/detectLockup'
 *    '<S666>/detectLockup'
 *    '<S694>/detectLockup'
 *    '<S722>/detectLockup'
 */
void CAVE_MachE_dSPACE_250912_detectLockup(real_T rtu_Tout, real_T rtu_Tfmaxs,
  real_T rtp_br, B_detectLockup_CAVE_MachE_dSPACE_250912_T *localB,
  DW_detectLockup_CAVE_MachE_dSPACE_250912_T *localDW,
  P_detectLockup_CAVE_MachE_dSPACE_250912_T *localP)
{
  int32_T rowIdx;
  boolean_T tmp;

  /* Gain: '<S535>/Output Damping' incorporates:
   *  Constant: '<S529>/Constant'
   */
  localB->OutputDamping = rtp_br * localP->Constant_Value;

  /* Sum: '<S535>/Sum2' */
  localB->Sum2 = (0.0 - rtu_Tout) - localB->OutputDamping;

  /* Sum: '<S535>/Sum1' */
  localB->Sum1 = localB->Sum2 + localB->OutputDamping;

  /* Abs: '<S532>/Abs' */
  localB->Abs = fabs(localB->Sum1);

  /* RelationalOperator: '<S532>/Relational Operator' */
  localB->RelationalOperator = (localB->Abs >= rtu_Tfmaxs);

  /* UnaryMinus: '<S536>/Unary Minus' */
  localB->UnaryMinus = -rtu_Tout;

  /* Abs: '<S537>/Abs' */
  localB->Abs_h = fabs(localB->UnaryMinus);

  /* RelationalOperator: '<S537>/Relational Operator' */
  localB->RelationalOperator_d = (localB->Abs_h <= rtu_Tfmaxs);

  /* UnitDelay: '<S534>/Unit Delay' */
  localB->UnitDelay = localDW->UnitDelay_DSTATE;

  /* CombinatorialLogic: '<S534>/Combinatorial  Logic' */
  tmp = localB->RelationalOperator_d;
  rowIdx = tmp;
  tmp = localB->RelationalOperator;
  rowIdx = (int32_T)(((uint32_T)rowIdx << 1) + tmp);
  tmp = localB->UnitDelay;
  rowIdx = (int32_T)(((uint32_T)rowIdx << 1) + tmp);

  /* CombinatorialLogic: '<S534>/Combinatorial  Logic' */
  localB->CombinatorialLogic = localP->CombinatorialLogic_table[(uint32_T)rowIdx];

  /* Update for UnitDelay: '<S534>/Unit Delay' */
  localDW->UnitDelay_DSTATE = localB->CombinatorialLogic;
}

