  /* Product: '<S115>/Product2' incorporates:
   *  Constant: '<S115>/VRef'
   */
  CAVE_MachE_dSPACE_250912_B.Product2_lc = CAVE_MachE_dSPACE_250912_B.Gain3_i *
    CAVE_MachE_dSPACE_250912_P.VRef_Value;

  /* Gain: '<S115>/Gain1' */
  CAVE_MachE_dSPACE_250912_B.APP1_CmdFinal_V =
    CAVE_MachE_dSPACE_250912_P.Gain1_Gain_k *
    CAVE_MachE_dSPACE_250912_B.Product2_lc;
